require_once __DIR__ . '/includes/auth.php';require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../config/schema.php';require_once __DIR__ . '/../includes/functions.php';ensureFullSchema($pdo);$pageTitle='Leituras';$f=$_GET['status']??'';$permit=['Nova','Confirmada','Agendada','Concluída','Cancelada'];$sql="SELECT l.*,s.nome AS servico_nome FROM leituras l LEFT JOIN servicos_baralho s ON s.id=l.servico_id";$p=[];if(in_array($f,$permit,true)){$sql.=" WHERE l.status=?";$p[]=$f;}$sql.=" ORDER BY l.criado_em DESC";$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();require __DIR__ . '/includes/header.php';?>
<div class="admin-top"><div><span class="section-kicker">ORÁCULO</span><h1>Leituras</h1><p>Solicitações de Baralho Cigano separadas dos pedidos de peças, mas integradas ao financeiro.</p></div></div><div class="filter-row admin-filters"><a class="filter-pill <?= !$f?'active':'' ?>" href="<?= BASE_URL ?>/admin/leituras.php">Todas</a><?php foreach($permit as $st): ?><a class="filter-pill <?= $f===$st?'active':'' ?>" href="?status=<?= urlencode($st) ?>"><?= e($st) ?></a><?php endforeach; ?></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Leitura</th><th>Tema</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['nome_cliente']) ?></strong><small><?= e($r['telefone']) ?></small></td><td><strong><?= e($r['servico_nome']?:'Leitura') ?></strong><small><?= e($r['codigo_acompanhamento']) ?></small></td><td><?= e($r['tema']?:'—') ?></td><td><?= dinheiro($r['valor_fechado']?:$r['preco_estimado']) ?></td><td><span class="<?= leituraStatusClass($r['status']) ?>"><?= e($r['status']) ?></span></td><td><a class="table-link" href="<?= BASE_URL ?>/admin/leitura.php?id=<?= (int)$r['id'] ?>">Abrir →</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-cell">Nenhuma leitura encontrada.</td></tr><?php endif; ?></tbody></table></div>
